// Kata kunci 1-kata yang rawan tabrakan antar-daerah — hanya dihitung skor rendah.
const KW_LEMAH = new Set([
  "utara", "selatan", "barat", "timur", "tengah", "raya", "pusat", "besar", "kota",
  "banda", "teluk", "naga", "bukit", "muara", "tanjung", "pangkalan", "kuala",
  "lubuk", "gunung", "sungai", "batu", "pondok", "bagian", "kepulauan",
]);

// Tebak unit PLN dari teks kota/alamat pelanggan.
// Return { up3, prov }: up3 "" bila tidak yakin; prov "" bila provinsi tak terdeteksi.
export function detectUnitPln(...parts) {
  const hay =
    " " +
    parts
      .filter(Boolean)
      .join(" ")
      .toLowerCase()
      .replace(/[^a-z0-9\s]/g, " ")
      .replace(/\s+/g, " ")
      .trim() +
    " ";
  if (hay.trim() === "") return { up3: "", prov: "" };

  let top = [];
  let topScore = 0;
  for (const u of PLN_UP3) {
    const shortName = u.up3.slice(4).toLowerCase(); // "UP3 PASURUAN" → "pasuruan"
    let s = 0;
    for (const k of u.kw) {
      if (!hay.includes(" " + k + " ")) continue;
      const w = k === shortName ? 4 : k.includes(" ") ? 3 : KW_LEMAH.has(k) ? 1 : 2;
      if (w > s) s = w;
    }
    if (s === 0) continue;
    if (s > topScore) {
      topScore = s;
      top = [u];
    } else if (s === topScore) {
      top.push(u);
    }
  }

  const uniq = [...new Map(top.map((u) => [u.up3, u])).values()];
  if (uniq.length === 1) return { up3: uniq[0].up3, prov: uniq[0].prov };
  if (uniq.length > 1) {
    const provs = [...new Set(uniq.map((u) => u.prov))];
    return { up3: "", prov: provs.length === 1 ? provs[0] : "" };
  }
  return { up3: "", prov: "" };
}
